"use strict";(self.webpackChunkenterprise_ai_agents_applied_ml_book=self.webpackChunkenterprise_ai_agents_applied_ml_book||[]).push([[8812],{3663(e,t,n){n.r(t),n.d(t,{assets:()=>c,contentTitle:()=>d,default:()=>g,frontMatter:()=>l,metadata:()=>i,toc:()=>p});const i=JSON.parse('{"id":"part1-enterprise-ai-delivery/hld-to-lld-sprint-plan","title":"LLD and Sprint Planning: Turn HLD into Buildable Work","description":"You have an approved (or conditionally approved) HLD for the Exec Document Q&A (cited RAG) pilot. Now your job as AI Lead is to translate \u201cboxes and arrows\u201d into implementable stories with clear owners, a vertical sli...","source":"@site/docs/part1-enterprise-ai-delivery/10-hld-to-lld-sprint-plan.mdx","sourceDirName":"part1-enterprise-ai-delivery","slug":"/part1-enterprise-ai-delivery/10-hld-to-lld-sprint-plan","permalink":"/tutorials/part1-enterprise-ai-delivery/10-hld-to-lld-sprint-plan","draft":false,"unlisted":false,"tags":[],"version":"current","lastUpdatedAt":1785375762000,"sidebarPosition":10,"frontMatter":{"title":"LLD and Sprint Planning: Turn HLD into Buildable Work","slug":"/part1-enterprise-ai-delivery/10-hld-to-lld-sprint-plan","description":"You have an approved (or conditionally approved) HLD for the Exec Document Q&A (cited RAG) pilot. Now your job as AI Lead is to translate \u201cboxes and arrows\u201d into implementable stories with clear owners, a vertical sli...","sidebar_label":"10. HLD to LLD and sprint plan","pagination_label":"10. HLD to LLD and sprint plan","hide_title":true,"hide_table_of_contents":true},"sidebar":"bookSidebar","previous":{"title":"9. Architecture review","permalink":"/tutorials/part1-enterprise-ai-delivery/09-architecture-review"},"next":{"title":"11. Provisioning, services, scale","permalink":"/tutorials/part1-enterprise-ai-delivery/11-provisioning-services-scale"}}');var r=n(4848),a=n(8453),s=n(8172);const o=JSON.parse('{"sourcePath":"part1-enterprise-ai-delivery/10-hld-to-lld-sprint-plan.html","route":"/part1-enterprise-ai-delivery/10-hld-to-lld-sprint-plan","kind":"chapter","partId":"part1","partLabel":"Part I - Enterprise AI Delivery Lifecycle","accent":"blue","heading":"Step 3: Convert HLD into LLD Tasks and a Sprint-Ready Plan","title":"LLD and Sprint Planning: Turn HLD into Buildable Work","description":"You have an approved (or conditionally approved) HLD for the Exec Document Q&A (cited RAG) pilot. Now your job as AI Lead is to translate \u201cboxes and arrows\u201d into implementable stories with clear owners, a vertical sli...","readingMinutes":5,"bodyClass":"","normalizeMath":false,"toc":[{"id":"principles","label":"1) Planning principles (enterprise reality)"},{"id":"epics","label":"2) Define epics (map directly to your HLD boxes)"},{"id":"verticalslice","label":"3) Define the vertical slice milestone (the most important planning move)"},{"id":"stories","label":"4) Turn epics into buildable stories (how to slice work)"},{"id":"acceptance","label":"5) Acceptance criteria (include safety gates, not just \u201cit works\u201d)"},{"id":"team","label":"6) Assign work to 5 direct reports (a practical team shape)"},{"id":"sprintplan","label":"7) Example sprint plan (2 sprints to a vertical slice)"},{"id":"definitionofdone","label":"8) Definition of Done (what \u201ccomplete\u201d means in this org)"}],"html":"<div class=\\"container\\">\\n    \\n    <p class=\\"lead\\">\\n      You have an approved (or conditionally approved) HLD for the <strong>Exec Document Q&amp;A (cited RAG)</strong> pilot.\\n      Now your job as AI Lead is to translate \u201cboxes and arrows\u201d into <strong>implementable stories</strong> with clear owners,\\n      a <strong>vertical slice milestone</strong>, and acceptance criteria that include <strong>safety gates</strong> \u2014 not just \u201cit works\u201d.\\n      This guide assumes you lead <strong>5 AI/ML/Software engineers</strong> in a large enterprise environment.\\n    </p>\\n\\n    <ul class=\\"toc\\">\\n      <li><a href=\\"#principles\\">Planning principles</a></li>\\n      <li><a href=\\"#epics\\">Define epics</a></li>\\n      <li><a href=\\"#verticalslice\\">Vertical slice milestone</a></li>\\n      <li><a href=\\"#stories\\">Write buildable stories</a></li>\\n      <li><a href=\\"#acceptance\\">Acceptance criteria (incl. safety)</a></li>\\n      <li><a href=\\"#team\\">Assign work to 5 engineers</a></li>\\n      <li><a href=\\"#sprintplan\\">Example sprint plan (2 sprints)</a></li>\\n      <li><a href=\\"#definitionofdone\\">Definition of Done</a></li>\\n    </ul>\\n\\n    <h2 id=\\"principles\\">1) Planning principles (enterprise reality)</h2>\\n    <div class=\\"card\\">\\n      <div class=\\"grid2\\">\\n        <div class=\\"box\\">\\n          <div class=\\"k\\">What makes a backlog \u201cbuildable\u201d</div>\\n          <ul>\\n            <li>Every item has an owner, inputs, outputs, and acceptance criteria</li>\\n            <li>Dependencies are explicit (IAM, networking, data access, secrets)</li>\\n            <li>Work is sliced end-to-end (vertical), not by layers only</li>\\n            <li>Safety gates are included as first-class requirements</li>\\n          </ul>\\n        </div>\\n        <div class=\\"box\\">\\n          <div class=\\"k\\">Common failure modes</div>\\n          <ul>\\n            <li>Only building \u201cthe model part\u201d without operability/audit</li>\\n            <li>Stories too large (\u201cbuild retrieval system\u201d) \u2192 unclear progress</li>\\n            <li>Security conditions treated as \u201clater\u201d \u2192 late rework</li>\\n            <li>Dependencies discovered mid-sprint \u2192 blocked delivery</li>\\n          </ul>\\n        </div>\\n      </div>\\n\\n      <div class=\\"ok\\">\\n        <strong>Lead-level mantra:</strong> \u201cWe deliver a safe end-to-end slice early, then improve quality and scale.\u201d\\n      </div>\\n    </div>\\n\\n    <h2 id=\\"epics\\">2) Define epics (map directly to your HLD boxes)</h2>\\n    <div class=\\"card\\">\\n      <p>\\n        Start by creating epics that mirror the architecture. For this project, a clean set is:\\n      </p>\\n      <ul>\\n        <li><strong>Epic A \u2014 Auth &amp; gating:</strong> OIDC validation, org allowlist, tenant mapping, bootstrap endpoint</li>\\n        <li><strong>Epic B \u2014 Ingestion pipeline:</strong> intake event, extraction, canonical store, indexing</li>\\n        <li><strong>Epic C \u2014 Retrieval:</strong> strict tenant/corpus filters, ranking, chunk fetch</li>\\n        <li><strong>Epic D \u2014 Prompting &amp; citations:</strong> context packing, citation format, refusal rules</li>\\n        <li><strong>Epic E \u2014 Audit &amp; observability:</strong> structured logs, traces, dashboards, runbook hooks</li>\\n        <li><strong>Epic F \u2014 Evaluation harness:</strong> golden set, citation correctness checks, regression gate in CI/CD</li>\\n      </ul>\\n\\n      <div class=\\"callout\\">\\n        <strong>Tip:</strong> If your architecture review produced \u201capproval conditions\u201d, create one epic or track lane for each condition\\n        so nothing gets lost.\\n      </div>\\n    </div>\\n\\n    <h2 id=\\"verticalslice\\">3) Define the vertical slice milestone (the most important planning move)</h2>\\n    <div class=\\"card\\">\\n      <p>\\n        A vertical slice is a thin, end-to-end path that proves the system works safely with real constraints.\\n        It is not \u201cproduction ready\u201d, but it is <strong>real</strong> and <strong>demoable</strong>.\\n      </p>\\n\\n      <div class=\\"ok\\">\\n        <strong>Vertical slice (Exec Doc Q&amp;A) \u2014 definition:</strong>\\n        <ul>\\n          <li>One user logs in (Workspace OIDC) \u2192 backend validates \u2192 returns identity</li>\\n          <li>One small approved corpus (e.g., 10 meeting notes) is ingested</li>\\n          <li>Query retrieves tenant/corpus-filtered chunks</li>\\n          <li>LLM returns an answer with citations (or refuses)</li>\\n          <li>Audit log is written (no sensitive snippet dumps)</li>\\n          <li>Golden set eval runs and produces a simple report</li>\\n        </ul>\\n      </div>\\n\\n      <div class=\\"warn\\">\\n        <strong>Anti-pattern:</strong> building \u201cingestion\u201d for weeks before any end-to-end query works.\\n        Your team should be able to run a demo early.\\n      </div>\\n    </div>\\n\\n    <h2 id=\\"stories\\">4) Turn epics into buildable stories (how to slice work)</h2>\\n    <div class=\\"card\\">\\n      <p>\\n        Each story should be deliverable in 1\u20134 days by one engineer and have clear testable outputs.\\n        Use a consistent story template:\\n      </p>\\n\\n      <table>\\n        <thead>\\n          <tr>\\n            <th>Story field</th>\\n            <th>What to write</th>\\n          </tr>\\n        </thead>\\n        <tbody>\\n          <tr>\\n            <td><strong>Title</strong></td>\\n            <td>Verb + object (e.g., \u201cImplement /auth/bootstrap identity endpoint\u201d)</td>\\n          </tr>\\n          <tr>\\n            <td><strong>Goal</strong></td>\\n            <td>What capability is enabled and for whom</td>\\n          </tr>\\n          <tr>\\n            <td><strong>Inputs</strong></td>\\n            <td>Request format, upstream data, required secrets</td>\\n          </tr>\\n          <tr>\\n            <td><strong>Outputs</strong></td>\\n            <td>Response format, side effects (DB rows, logs, events)</td>\\n          </tr>\\n          <tr>\\n            <td><strong>Acceptance criteria</strong></td>\\n            <td>Functional + safety + observability tests</td>\\n          </tr>\\n          <tr>\\n            <td><strong>Dependencies</strong></td>\\n            <td>IAM, networking, platform tickets, approvals</td>\\n          </tr>\\n        </tbody>\\n      </table>\\n\\n      <h3 id=\\"example-story-breakdown-one-epic\\">Example story breakdown (one epic)</h3>\\n      <ul>\\n        <li><strong>Auth/gating:</strong> \u201cVerify JWT\u201d, \u201cCheck org allowlist\u201d, \u201cMap tenant\u201d, \u201cProvision user\u201d, \u201cReturn /me\u201d</li>\\n        <li><strong>Retrieval:</strong> \u201cIndex schema includes tenant/corpus tags\u201d, \u201cSearch with filters\u201d, \u201cFetch chunks\u201d</li>\\n        <li><strong>Prompting:</strong> \u201cFormat citations\u201d, \u201cRefuse when insufficient context\u201d, \u201cRedact patterns\u201d</li>\\n      </ul>\\n    </div>\\n\\n    <h2 id=\\"acceptance\\">5) Acceptance criteria (include safety gates, not just \u201cit works\u201d)</h2>\\n    <div class=\\"card\\">\\n      <p>\\n        In GenAI, acceptance criteria must include correctness, leakage prevention, and governance.\\n        Use the \u201c3-layer\u201d criteria pattern:\\n      </p>\\n\\n      <div class=\\"grid2\\">\\n        <div class=\\"box\\">\\n          <div class=\\"k\\">Functional</div>\\n          <ul>\\n            <li>Endpoint works for happy path</li>\\n            <li>Correct request/response schema</li>\\n            <li>Handles expected error cases</li>\\n          </ul>\\n        </div>\\n        <div class=\\"box\\">\\n          <div class=\\"k\\">Safety &amp; security</div>\\n          <ul>\\n            <li>Tenant/corpus filters enforced</li>\\n            <li>Prompt injection mitigations applied</li>\\n            <li>Refusal behavior when evidence is missing</li>\\n          </ul>\\n        </div>\\n      </div>\\n\\n      <div class=\\"grid2\\">\\n        <div class=\\"box\\">\\n          <div class=\\"k\\">Operability</div>\\n          <ul>\\n            <li>Structured logs with request_id/user/tenant</li>\\n            <li>Metrics for latency and failure codes</li>\\n            <li>Tracing across retrieval + LLM call</li>\\n          </ul>\\n        </div>\\n        <div class=\\"box\\">\\n          <div class=\\"k\\">Evidence</div>\\n          <ul>\\n            <li>Unit tests + integration test runs</li>\\n            <li>Golden set eval report updated</li>\\n            <li>Demo script for stakeholders</li>\\n          </ul>\\n        </div>\\n      </div>\\n\\n      <div class=\\"ok\\">\\n        <strong>Key acceptance gate:</strong> \u201cCross-tenant retrieval attempt returns zero results (and logs an audit event).\u201d\\n      </div>\\n    </div>\\n\\n    <h2 id=\\"team\\">6) Assign work to 5 direct reports (a practical team shape)</h2>\\n    <div class=\\"card\\">\\n      <p>\\n        With 5 engineers, assign ownership by <strong>stream</strong> but ensure the vertical slice comes together.\\n        A common structure:\\n      </p>\\n\\n      <table>\\n        <thead>\\n          <tr>\\n            <th>Engineer (example)</th>\\n            <th>Primary stream</th>\\n            <th>Deliverables</th>\\n          </tr>\\n        </thead>\\n        <tbody>\\n          <tr>\\n            <td>Eng 1</td>\\n            <td>Auth &amp; identity</td>\\n            <td>/auth/bootstrap, tenant mapping, org allowlist gate, user provisioning</td>\\n          </tr>\\n          <tr>\\n            <td>Eng 2</td>\\n            <td>Ingestion</td>\\n            <td>Pub/Sub/Tasks wiring, extractor stub, canonical store writes, index writes</td>\\n          </tr>\\n          <tr>\\n            <td>Eng 3</td>\\n            <td>Retrieval</td>\\n            <td>Strict filters, top-k search, chunk fetch, ranking tuning hooks</td>\\n          </tr>\\n          <tr>\\n            <td>Eng 4</td>\\n            <td>Prompting &amp; citations</td>\\n            <td>Context packing, citation format, refusal rules, redaction hooks</td>\\n          </tr>\\n          <tr>\\n            <td>Eng 5</td>\\n            <td>Evals + observability</td>\\n            <td>Golden set harness, citation correctness checks, dashboards/alerts, runbook skeleton</td>\\n          </tr>\\n        </tbody>\\n      </table>\\n\\n      <div class=\\"callout\\">\\n        <strong>Your role:</strong> manage integration points (contracts, schemas), sequencing, and keep \u201capproval conditions\u201d tracked.\\n        You should also reserve time for cross-cutting reviews and stakeholder updates.\\n      </div>\\n    </div>\\n\\n    <h2 id=\\"sprintplan\\">7) Example sprint plan (2 sprints to a vertical slice)</h2>\\n    <div class=\\"card\\">\\n      <p>\\n        Example assumes 2-week sprints. The goal is a demoable vertical slice by the end of Sprint 1 or early Sprint 2.\\n      </p>\\n\\n      <h3 id=\\"sprint-1-vertical-slice-foundations-end-to-end-demo\\">Sprint 1 \u2014 Vertical slice foundations (end-to-end demo)</h3>\\n      <table>\\n        <thead>\\n          <tr>\\n            <th>Epic</th>\\n            <th>Stories (examples)</th>\\n            <th>Acceptance focus</th>\\n          </tr>\\n        </thead>\\n        <tbody>\\n          <tr>\\n            <td>Auth/gating</td>\\n            <td>/auth/bootstrap validates JWT; org allowlist check; tenant mapping; user row create-if-missing</td>\\n            <td>403 if not allowed; stable user mapping; audit log entry</td>\\n          </tr>\\n          <tr>\\n            <td>Ingestion</td>\\n            <td>Ingest 10 sample docs into canonical store; write minimal index entries with tenant/corpus tags</td>\\n            <td>Repeatable ingestion; no cross-tenant tags; basic error handling</td>\\n          </tr>\\n          <tr>\\n            <td>Retrieval</td>\\n            <td>Search endpoint with strict tenant/corpus filters; returns chunk IDs and text</td>\\n            <td>Cross-tenant search returns 0; latency baseline measured</td>\\n          </tr>\\n          <tr>\\n            <td>Prompting/citations</td>\\n            <td>RAG prompt template; citations required; refusal when insufficient evidence</td>\\n            <td>No uncited answers; refusal cases tested</td>\\n          </tr>\\n          <tr>\\n            <td>Obs/audit</td>\\n            <td>Structured log schema; request_id; traces across retrieval + LLM</td>\\n            <td>No raw snippets in logs; dashboard stub exists</td>\\n          </tr>\\n          <tr>\\n            <td>Evals</td>\\n            <td>Golden set (10\u201320 Qs); basic evaluator: citation presence + answer groundedness checklist</td>\\n            <td>Eval report produced in CI; baseline recorded</td>\\n          </tr>\\n        </tbody>\\n      </table>\\n\\n      <h3 id=\\"sprint-2-quality-safety-hardening-pilot-ready\\">Sprint 2 \u2014 Quality + safety hardening (pilot-ready)</h3>\\n      <ul>\\n        <li>Improve retrieval quality (hybrid ranking, chunking refinements)</li>\\n        <li>Add stronger leakage tests and prompt injection tests</li>\\n        <li>Add redaction rules and validate policy compliance</li>\\n        <li>Expand eval set + add regression gates (must not degrade)</li>\\n        <li>Operational readiness: alerts, runbook, on-call handoff</li>\\n      </ul>\\n    </div>\\n\\n    <h2 id=\\"definitionofdone\\">8) Definition of Done (what \u201ccomplete\u201d means in this org)</h2>\\n    <div class=\\"card\\">\\n      <p>\\n        Define DoD once and apply to every story. This prevents \u201cworks on my machine\u201d delivery.\\n      </p>\\n      <ul>\\n        <li>Code merged with tests (unit + at least one integration test)</li>\\n        <li>Observability: logs/metrics/traces updated for the feature</li>\\n        <li>Security: tenant/corpus enforcement verified (test case included)</li>\\n        <li>Documentation: README snippet or runbook note updated</li>\\n        <li>Demoable: a curl/script or Postman request exists</li>\\n      </ul>\\n\\n      <div class=\\"ok\\">\\n        <strong>Lead-level improvement:</strong> add a \u201csafety test\u201d checkbox to every story by default.\\n      </div>\\n    </div>\\n\\n    <div class=\\"tr-note\\">\\n      <strong>Backlog scale</strong>\\n      A realistic first-two-sprint backlog contains roughly 20\u201340 stories with\\n      owners and acceptance criteria spanning GKE, Cloud SQL, GCS,\\n      Pub/Sub or Cloud Tasks, and the selected retrieval service\\n      (Vertex AI Search or OpenSearch).\\n    </div>\\n  </div>"}'),l={title:"LLD and Sprint Planning: Turn HLD into Buildable Work",slug:"/part1-enterprise-ai-delivery/10-hld-to-lld-sprint-plan",description:"You have an approved (or conditionally approved) HLD for the Exec Document Q&A (cited RAG) pilot. Now your job as AI Lead is to translate \u201cboxes and arrows\u201d into implementable stories with clear owners, a vertical sli...",sidebar_label:"10. HLD to LLD and sprint plan",pagination_label:"10. HLD to LLD and sprint plan",hide_title:!0,hide_table_of_contents:!0},d=void 0,c={},p=[];function u(e){return(0,r.jsx)(s.A,{content:o})}function g(e={}){const{wrapper:t}={...(0,a.R)(),...e.components};return t?(0,r.jsx)(t,{...e,children:(0,r.jsx)(u,{...e})}):u()}}}]);